export function translate(languageCode, key, params) {
  const dict = TRANSLATIONS[languageCode] || TRANSLATIONS[DEFAULT_LANGUAGE];
  const raw = dict[key] ?? TRANSLATIONS[DEFAULT_LANGUAGE][key] ?? key;
  if (!params) return raw;
  return Object.keys(params).reduce(
    (str, paramKey) => str.replaceAll(`{${paramKey}}`, String(params[paramKey])),
    raw
  );
}
